-- One requested test (a ticked box in section 7) of a transplant recipient request.

CREATE TABLE medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    request_id UUID NOT NULL REFERENCES medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request(id) ON DELETE CASCADE,
    test_code VARCHAR(60) NOT NULL CHECK (test_code IN ('list-registration-first-typing-and-retyping', 'list-registration-returning-to-list', 'list-registration-other', 'deceased-donor-full-crossmatch', 'deceased-donor-day-of-transplant', 'living-donor-full-crossmatch', 'living-donor-day-of-transplant', 'living-donor-virtual-crossmatch', 'living-donor-match-grade', 'living-donor-abo-titres-only', 'autologous-crossmatch', 'hla-antibody-monitoring-routine-transplant-list', 'hla-antibody-monitoring-routine-post-transplant', 'hla-antibody-monitoring-post-transfusion', 'hla-rejection-investigation', 'abo-incompatible-transplant-monitoring', 'red-cell-antibody-follow-up')),
    test_detail VARCHAR(255) NOT NULL DEFAULT ''
);

CREATE TRIGGER trigger_mrtrr_test_updated_at
    BEFORE UPDATE ON medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test
    FOR EACH ROW
    EXECUTE FUNCTION medical_renal_transplant_recipient_request.set_updated_at();

COMMENT ON TABLE medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test IS
    'One requested test of a transplant recipient request, such as typing, crossmatch, HLA antibody monitoring or rejection investigation.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test.created_at IS
    'Timestamp when the record was created.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test.request_id IS
    'Foreign key to the parent request.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test.test_code IS
    'Requested test code, one of the 17 tests offered in section 7 of the request.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test.test_detail IS
    'Free-text detail, for example the specific test when "other" is chosen (e.g. ABO only).';

CREATE UNIQUE INDEX index_mrtrr_test_request_id_test_code
    ON medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_test(request_id, test_code) WHERE deleted_at IS NULL;

-- ========================================================================
-- END 05_create_table_medical_renal_transplant_recipient_request_test.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 06_create_table_medical_renal_transplant_recipient_request_grade.sql
-- ========================================================================

-- Computed grading result for a renal transplant recipient request (four-axis engine).

CREATE TABLE medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    request_id UUID NOT NULL UNIQUE REFERENCES medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request(id) ON DELETE CASCADE,
    appropriateness_score INTEGER CHECK (appropriateness_score IS NULL OR appropriateness_score BETWEEN 1 AND 9),
    appropriateness_band VARCHAR(25) NOT NULL DEFAULT '' CHECK (appropriateness_band IN ('usually-appropriate', 'may-be-appropriate', 'usually-not-appropriate', '')),
    identity_safety_band VARCHAR(15) NOT NULL DEFAULT '' CHECK (identity_safety_band IN ('ok', 'caution', 'reject-risk', '')),
    completeness_percent INTEGER CHECK (completeness_percent IS NULL OR completeness_percent BETWEEN 0 AND 100),
    triage_tier VARCHAR(15) NOT NULL DEFAULT '' CHECK (triage_tier IN ('routine', 'urgent', 'emergency', 'stat', '')),
    target_timeframe VARCHAR(50) NOT NULL DEFAULT '',
    required_samples_summary VARCHAR(500) NOT NULL DEFAULT '',
    recommendation VARCHAR(20) NOT NULL DEFAULT '' CHECK (recommendation IN ('accept', 'query-referrer', 'reject', '')),
    clinician_notes VARCHAR(1000) NOT NULL DEFAULT '',
    signed_at TIMESTAMPTZ,
    graded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TRIGGER trigger_mrtrr_grade_updated_at
    BEFORE UPDATE ON medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade
    FOR EACH ROW
    EXECUTE FUNCTION medical_renal_transplant_recipient_request.set_updated_at();

COMMENT ON TABLE medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade IS
    'Computed result of the four-axis engine for one request: test-selection appropriateness, identity / sample safety, completeness and triage priority, plus the derived sample requirements and vetting recommendation.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.created_at IS
    'Timestamp when the record was created.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.request_id IS
    'Foreign key to the graded request (one grade per request).';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.appropriateness_score IS
    'Axis A test-selection appropriateness, 1-9 ordinal. No published score exists for histocompatibility test selection; anchored on BSHI / EFI guidance and labelled as such.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.appropriateness_band IS
    'Axis A band: usually-appropriate (7-9), may-be-appropriate (4-6), usually-not-appropriate (1-3).';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.identity_safety_band IS
    'Axis B identity / sample safety band: ok, caution, reject-risk.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.completeness_percent IS
    'Axis C request completeness, 0-100 percent.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.triage_tier IS
    'Axis D triage tier: routine, urgent, emergency, stat.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.target_timeframe IS
    'Target turnaround implied by the triage tier (local policy; see spec).';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.required_samples_summary IS
    'Sample tubes and volumes the requested tests need, derived from the tests chosen.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.recommendation IS
    'Vetting recommendation: accept, query-referrer, reject.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.clinician_notes IS
    'Free-text vetting notes.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.signed_at IS
    'Timestamp of the vetting person''s electronic signature.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade.graded_at IS
    'Timestamp when the engine last computed the result.';

-- ========================================================================
-- END 06_create_table_medical_renal_transplant_recipient_request_grade.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 07_create_table_medical_renal_transplant_recipient_request_grade_rule.sql
-- ========================================================================

-- Audit trail of every scoring rule that fired for a renal transplant recipient request.

CREATE TABLE medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    grade_id UUID NOT NULL REFERENCES medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(40) NOT NULL,
    axis VARCHAR(20) NOT NULL DEFAULT '' CHECK (axis IN ('appropriateness', 'identity', 'completeness', 'triage', '')),
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE TRIGGER trigger_mrtrr_grade_rule_updated_at
    BEFORE UPDATE ON medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule
    FOR EACH ROW
    EXECUTE FUNCTION medical_renal_transplant_recipient_request.set_updated_at();

COMMENT ON TABLE medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule IS
    'Audit trail of every appropriateness / identity / completeness / triage rule that fired for this request.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule.created_at IS
    'Timestamp when the record was created.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule.grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule.rule_id IS
    'Stable rule identifier (for example R-ID-3PT-01).';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule.axis IS
    'Scoring axis the rule belongs to: appropriateness, identity, completeness, triage.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule.category IS
    'Category the rule relates to.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule.description IS
    'Human-readable description of why the rule fired.';

CREATE INDEX index_mrtrr_grade_rule_grade_id ON medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_rule(grade_id);

-- ========================================================================
-- END 07_create_table_medical_renal_transplant_recipient_request_grade_rule.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 08_create_table_medical_renal_transplant_recipient_request_grade_flag.sql
-- ========================================================================

-- Safety-critical flags for a renal transplant recipient request, independent of the axes.

CREATE TABLE medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    grade_id UUID NOT NULL REFERENCES medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(50) NOT NULL DEFAULT '' CHECK (category IN ('day-of-transplant-stat', 'virtual-crossmatch-without-antibody-profile', 'sensitised-recipient', 'missing-abo-group', 'abo-incompatible-without-dfpp-status', 'hand-labelled-sample-required', 'identity-mismatch-risk', 'urgent-without-reason', 'missing-sensitisation-history', 'post-transfusion-without-dates', 'other', '')),
    priority VARCHAR(10) NOT NULL DEFAULT '' CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE TRIGGER trigger_mrtrr_grade_flag_updated_at
    BEFORE UPDATE ON medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION medical_renal_transplant_recipient_request.set_updated_at();

COMMENT ON TABLE medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag IS
    'Safety-critical flags that fire independently of the four axes, with priority and a suggested action for the laboratory and requester.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.created_at IS
    'Timestamp when the record was created.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.flag_id IS
    'Stable flag identifier (for example F-DAY-OF-TRANSPLANT-001).';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.category IS
    'Flag category.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.priority IS
    'Priority: low, medium, high.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.description IS
    'Human-readable description of what fired the flag.';
COMMENT ON COLUMN medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag.suggested_action IS
    'Suggested action for the requester or laboratory.';

CREATE INDEX index_mrtrr_grade_flag_grade_id ON medical_renal_transplant_recipient_request.medical_renal_transplant_recipient_request_grade_flag(grade_id);

-- ========================================================================
-- END 08_create_table_medical_renal_transplant_recipient_request_grade_flag.sql
